protocol ExchangeRateSource {             // domain-owned port
    func rate(from: Currency, to: Currency) throws -> Decimal
}

struct ExchangeService {                  // value type, no shared state
    let rates: any ExchangeRateSource

    func convert(_ amount: Money, to target: Currency) throws -> Money {
        try amount.times(rates.rate(from: amount.currency, to: target)).in(target)
    }
}

